from attrs import define, field, validators


def conv_bool_as_lowercase_str(b):
    if b is not None:
        conv = str(b).lower()
        return conv if conv in ("true", "false") else "false"


def conv_str_with_list_of_values(s):
    if s:
        return s.replace(",", " ").replace("  ", " ")


def validate_verdict(self, _, verdicts_str):
    if not verdicts_str:
        return

    supported_verdicts = (
        "pass",
        "fail",
        "denial-of-service",
        "n/a",
        "no-interop",
        "skip",
        "degradation-of-service",
        "user-stop",
        "suite-error",
        "aborted",
    )

    verdicts_list = verdicts_str.split(" ")
    for v in verdicts_list:
        if v not in supported_verdicts:
            raise ValueError(f"Provided incorrect verdict: {v}")


def validate_instrumentation(self, _, instrumentation_str):
    if not instrumentation_str:
        return

    supported_methods = (
        "all",
        "valid-external",
        "valid",
        "external",
        "connection",
        "snmp",
        "snmptrap",
        "isasecure",
        "safeguard",
        "syslog",
    )

    instrumentations_list = instrumentation_str.split(" ")
    for i in instrumentations_list:
        if i not in supported_methods:
            raise ValueError(f"Provided incorrect instrumentation method: {i}")


@define
class RerunSuiteArgumentsValidator:
    suite = field(validator=validators.optional(validators.instance_of(str)))
    suite_name = field(validator=validators.optional(validators.instance_of(str)))
    file_path = field(validator=validators.optional(validators.instance_of(str)))
    load_suite = field(converter=conv_bool_as_lowercase_str)
    setting = field(validator=validators.optional(validators.instance_of(str)))
    verdict = field(converter=conv_str_with_list_of_values, validator=validate_verdict)
    type_of_rerun = field(
        validator=validators.optional(validators.in_(["index", "hash", "group"])),
    )
    instrumentation = field(
        converter=conv_str_with_list_of_values,
        validator=validate_instrumentation,
    )
    rerun_preceding = field()

    @rerun_preceding.validator
    def _(self, attribute, value):
        if value and self.type_of_rerun != "index":
            raise ValueError("'rerun_preceding' can be used only with 'index' rerun type")
